-- Тема 19: Проезд пешеходных переходов — топик id=19, категория id=6
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(6,19,'Как должен действовать водитель при приближении к нерегулируемому пешеходному переходу, если пешеход стоит на тротуаре у края проезжей части?',
'["Водитель может продолжать движение, если пешеход явно не начал переход","Обязан всегда останавливаться при виде пешехода у перехода","Обязан подать звуковой сигнал","Должен снизить скорость до полной остановки в любом случае"]'::jsonb,0,
'Водитель обязан уступить дорогу пешеходам, которые переходят проезжую часть или вступили на неё для перехода; пешеход, только стоящий на тротуаре, не имеет безусловного приоритета, но требует повышенного внимания.',1),
(6,19,'Разрешён ли обгон на нерегулируемом пешеходном переходе?',
'["Запрещён","Разрешён при отсутствии пешеходов","Разрешён только для мотоциклов","Разрешён, если видимость хорошая"]'::jsonb,0,
'Обгон на пешеходных переходах запрещён Правилами дорожного движения независимо от наличия пешеходов.',2),
(6,19,'Что обязан сделать водитель при остановке автобуса на регулируемом перекрёстке с открытыми дверями для высадки пассажиров вблизи пешеходного перехода?',
'["Соблюдать особую осторожность, так как пассажиры могут переходить дорогу","Продолжать движение без ограничений","Уступить только пассажирам с детьми","Не обращать внимания, если горит зелёный сигнал"]'::jsonb,0,
'Вблизи остановок маршрутных ТС и пешеходных переходов водитель должен проявлять особую осторожность из-за возможного появления пешеходов.',3),
(6,19,'Как должен действовать водитель при повороте направо, если на пешеходном переходе, на который он поворачивает, находятся пешеходы?',
'["Уступить дорогу пешеходам, завершающим переход","Пешеходы обязаны остановиться и пропустить автомобиль","Продолжить движение, так как у водителя приоритет при повороте","Подать сигнал и продолжить движение"]'::jsonb,0,
'При повороте направо или налево водитель обязан уступить дорогу пешеходам, переходящим проезжую часть дороги, на которую он поворачивает.',4),
(6,19,'Разрешена ли остановка ТС на пешеходном переходе и ближе 5 метров перед ним?',
'["Запрещена","Разрешена на срок не более 1 минуты","Разрешена в случае затора","Разрешена, если нет пешеходов поблизости"]'::jsonb,0,
'Остановка и стоянка запрещены на пешеходных переходах и ближе 5 метров перед ними, за исключением вынужденной остановки.',5),
(6,19,'Что должен делать водитель, если перед регулируемым пешеходным переходом остановилось другое ТС, закрывающее обзор проезжей части?',
'["Снизить скорость и убедиться в отсутствии пешеходов перед продолжением движения","Продолжить движение с той же скоростью","Обогнать остановившееся ТС","Подать звуковой сигнал и проехать"]'::jsonb,0,
'Если перед нерегулируемым пешеходным переходом остановилось или снизило скорость ТС, водитель других ТС, движущихся по соседним полосам, должен снизить скорость или остановиться с учётом возможного наличия пешеходов, закрытых остановившимся ТС.',6);

-- Тема 8: Начало движения, манёврирование — топик id=8, категория id=7
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(7,8,'Когда водитель обязан подавать сигнал поворота световыми указателями?',
'["Перед началом движения, перестроением, поворотом, разворотом или остановкой","Только на перекрёстках","Только вне населённых пунктов","Сигнал не обязателен, если дорога пуста"]'::jsonb,0,
'Сигналы поворота должны подаваться перед началом движения, перестроением, поворотом, разворотом и остановкой заблаговременно и прекращаться сразу после завершения манёвра.',1),
(7,8,'Что должен делать водитель при выполнении разворота вне перекрёстка?',
'["Убедиться в безопасности манёвра и отсутствии помех попутным и встречным ТС","Разворот вне перекрёстка запрещён в любом случае","Достаточно включить сигнал поворота","Нужно дождаться сотрудника ГИБДД"]'::jsonb,0,
'Перед разворотом вне перекрёстка водитель обязан убедиться в безопасности манёвра, отсутствии помех другим участникам движения, и что ширина проезжей части достаточна для выполнения манёвра.',2),
(7,8,'Кто пользуется преимуществом при одновременном перестроении ТС, движущихся попутно без изменения направления движения?',
'["Преимущество имеет ТС, движущееся без изменения направления (относительно которого перестраивается другое)","Всегда ТС, движущееся правее","Тот, кто первым включил сигнал","Оба ТС должны уступить друг другу"]'::jsonb,0,
'При одновременном перестроении преимущество имеет ТС, движущееся без изменения направления движения, то есть по отношению к которому выполняется перестроение.',3),
(7,8,'Разрешён ли разворот в местах пешеходных переходов?',
'["Запрещён","Разрешён при отсутствии пешеходов","Разрешён только для легковых автомобилей","Разрешён при малой интенсивности движения"]'::jsonb,0,
'Разворот запрещён на пешеходных переходах, в тоннелях, на мостах, эстакадах и путепроводах, а также под ними и в местах остановок маршрутных ТС.',4),
(7,8,'Что обязан сделать водитель перед выездом на дорогу с прилегающей территории?',
'["Уступить дорогу ТС и пешеходам, движущимся по дороге, а при необходимости пересечения тротуара — пешеходам, идущим по нему","Уступают только пешеходы, идущие по тротуару","Никаких требований нет, если территория прилегающая","Достаточно снизить скорость"]'::jsonb,0,
'При выезде на дорогу с прилегающей территории водитель обязан уступить дорогу ТС и пешеходам, движущимся по этой дороге, а при пересечении тротуара или обочины — пешеходам, движущимся по ним.',5),
(7,8,'Подача сигнала поворота освобождает ли водителя от принятия мер предосторожности при манёвре?',
'["Нет, сигнал не даёт преимущества и не освобождает от осторожности","Да, сигнал даёт полное право на манёвр","Да, если сигнал подан заблаговременно","Освобождает только на главной дороге"]'::jsonb,0,
'Подача сигнала поворота не даёт водителю преимущества и не освобождает его от принятия мер предосторожности при выполнении манёвра.',6);
